gaco(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
gacn(){return"\u062f\u06b5\u0646\u06cc\u0627\u06cc\u062a \u0644\u06d5 \u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u0626\u06d5\u0645 \u062f\u06a9\u062a\u06c6\u0631\u06d5\u061f"},
acl(a){return a+" \u0628\u06d5 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u0648 \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0647\u06cc\u0686 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5. \u062a\u06d5\u0646\u0647\u0627 \u0626\u06d5\u06af\u06d5\u0631 \u0626\u06d5\u0645 \u062f\u06a9\u062a\u06c6\u0631\u06d5 \u0647\u06cc\u0686 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u0646\u06d5\u0628\u06ce\u062a\u060c \u06cc\u0627\u0646 \u0626\u06d5\u0645 \u0644\u0642\u06d5 \u0647\u06ce\u0634\u062a\u0627 \u0646\u0648\u06ce \u0628\u06ce\u062a \u0695\u06ce\u06af\u06d5\u067e\u06ce\u062f\u0631\u0627\u0648\u06d5 \u2014 \u0646\u06d5\u0628\u06ce\u062a\u060c \u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06cc \u0628\u06a9\u06d5 \u0644\u06d5\u0628\u0631\u06cc \u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5."},
gacm(){return"\u062f\u06a9\u062a\u06c6\u0631 \u0628\u06d5 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u0633\u0695\u0627\u06cc\u06d5\u0648\u06d5."},
gRO(){return"\u0646\u06d5\u062a\u0648\u0627\u0646\u0631\u0627 \u0628\u06d5 \u062f\u06b5\u0646\u06cc\u0627\u06cc\u06cc\u06d5\u0648\u06d5 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc Dentist Clinic \u06cc \u0626\u06d5\u0645 \u062f\u06a9\u062a\u06c6\u0631\u06d5 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u0631\u06ce\u062a \u2014 \u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5 \u0695\u06d5\u062a\u062f\u06d5\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
