gaeI(){return"\u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0646\u0631\u062e\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0645\u0627\u062f\u06d5\u06a9\u06d5. \u0646\u0631\u062e\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u062f\u06d5\u0628\u06ce\u062a."},
aeH(a){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc "+a},
gaeL(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc"},
gaeK(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u0645"},
gaeG(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u0632\u06cc\u0627\u062a\u0631"},
afv(a){return"\u0695\u06ce\u0698\u06d5\u06cc \u06a9\u06c6\u0645\u06cc\u0633\u06cc\u06c6\u0646 \u2014 "+a},
gafu(){return"\u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0695\u06ce\u0698\u06d5\u06cc \u06a9\u06c6\u0645\u06cc\u0633\u06cc\u06c6\u0646\u06cc \u06cc\u06d5\u06a9\u0633\u0627\u0646\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5. \u0628\u06d5\u0647\u0627\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0626\u06d5\u0645 \u0645\u0627\u062f\u06d5\u06cc\u06d5 \u06a9\u0627\u0631\u062f\u06d5\u06a9\u0627\u062a."},
