gagn(){return"\u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0695\u06ce\u0698\u06d5\u06cc \u06a9\u06c6\u0645\u06cc\u0633\u06cc\u06c6\u0646 \u0628\u06c6 \u0647\u06d5\u0631 \u0645\u0627\u062f\u06d5\u06cc\u06d5\u06a9"},
